import numpy as np

def running_avg_foreground(frames, alpha, threshold):
    bg = frames[0].astype(np.float32)
    for frame in frames[1:-1]:
        bg = (1.0 - alpha) * bg + alpha * frame.astype(np.float32)
    last = frames[-1].astype(np.float32)
    diff = np.abs(last - bg)
    return (diff > threshold).astype(np.uint8)
